#include <stdio.h>

// Function to perform the Quick Sort algorithm
void quickSort(int arr[], int low, int high) {
 if (low < high) {
 int pivot = arr[high];
 int i = low - 1;

for (int j = low; j <= high - 1; j++) {
 if (arr[j] < pivot) {
 i++;
 int temp = arr[i];
 arr[i] = arr[j];
 arr[j] = temp;
 }
 }

int temp = arr[i + 1];
 arr[i + 1] = arr[high];
 arr[high] = temp;

int partitionIndex = i + 1;

quickSort(arr, low, partitionIndex - 1);
 quickSort(arr, partitionIndex + 1, high);
 }
}

// Function to merge two sorted arrays into one sorted array
void mergeSortedArrays(int arr1[], int n1, int arr2[], int n2, int merged[]) {
 int i = 0, j = 0, k = 0;

while (i < n1 && j < n2) {
 if (arr1[i] < arr2[j]) {
 merged[k++] = arr1[i++];
 } else {
 merged[k++] = arr2[j++];
 }
 }

while (i < n1 && j < n2) {
 if (arr1[i] < arr2[j]) {
 merged[k++] = arr1[i++];
 } else {
 merged[k++] = arr2[j++];
 }
 }

while (i < n1) {
 merged[k++] = arr1[i++];
 }

while (j < n2) {
 merged[k++] = arr2[j++];
 }
}

